const MARK_SECTIONS = {"1":[{"title":"Jan Křtitel připravuje cestu","range":"Mk 1,1–8","thoughts":[],"verses":[[1,"Počátek evangelia Ježíše Krista, Božího Syna."],[2,"Jak je napsáno v prorocích: „Hle, posílám před tebou svého posla, který připraví tvou cestu.“"],[3,"„Hlas volajícího na poušti: Připravte Pánovu cestu, narovnejte jeho stezky.“"],[4,"Jan křtil na poušti a hlásal křest pokání na odpuštění hříchů."],[5,"Přicházela k němu celá judská krajina i lidé z Jeruzaléma. Vyznávali své hříchy a nechávali se od něho křtít v Jordánu."],[6,"Jan nosil oděv z velbloudí srsti, kolem pasu kožený pás a jedl kobylky a lesní med."],[7,"Kázal: „Za mnou přichází někdo silnější než já. Nejsem hoden ani se sklonit a rozvázat mu řemínek u sandálů.“"],[8,"„Já jsem vás křtil vodou, ale on vás bude křtít Duchem svatým.“"]]},{"title":"Ježíšův křest a pokušení","range":"Mk 1,9–13","thoughts":[],"verses":[[9,"V těch dnech přišel Ježíš z galilejského Nazareta a Jan ho pokřtil v Jordánu."],[10,"Hned když vystupoval z vody, uviděl otevřená nebesa a Ducha, jak na něj sestupuje jako holubice."],[11,"A z nebe zazněl hlas: „Ty jsi můj milovaný Syn, v tobě mám zalíbení.“"],[12,"Hned potom ho Duch vedl na poušť."],[13,"Byl na poušti čtyřicet dní a satan ho pokoušel. Byl mezi divokými zvířaty a andělé mu sloužili."]]},{"title":"Začátek Ježíšova působení","range":"Mk 1,14–15","thoughts":[],"verses":[[14,"Když byl Jan uvězněn, přišel Ježíš do Galileje a hlásal evangelium Božího království."],[15,"Říkal: „Čas se naplnil a Boží království se přiblížilo. Čiňte pokání a věřte evangeliu.“"]]},{"title":"Povolání prvních učedníků","range":"Mk 1,16–20","thoughts":[],"verses":[[16,"Když šel podél Galilejského jezera, uviděl Šimona a jeho bratra Ondřeje, jak vrhají síť do jezera, protože byli rybáři."],[17,"Ježíš jim řekl: „Pojďte za mnou a udělám z vás rybáře lidí.“"],[18,"Oni hned nechali sítě a šli za ním."],[19,"Když poodešel o něco dál, uviděl Jakuba, syna Zebedeova, a jeho bratra Jana, jak na lodi spravují sítě."],[20,"Hned je zavolal. Oni nechali svého otce Zebedea na lodi s najatými pracovníky a šli za ním."]]},{"title":"Ježíš učí v Kafarnaum","range":"Mk 1,21–28","thoughts":[],"verses":[[21,"Přišli do Kafarnaum. Hned v sobotu Ježíš vešel do synagogy a učil."],[22,"Lidé žasli nad jeho učením, protože je učil jako ten, kdo má autoritu, a ne jako učitelé Zákona."],[23,"V jejich synagoze byl člověk s nečistým duchem. Ten vykřikl:"],[24,"„Co je ti po nás, Ježíši Nazaretský? Přišel jsi nás zahubit? Vím, kdo jsi: Boží Svatý.“"],[25,"Ježíš mu pohrozil: „Mlč a vyjdi z něho!“"],[26,"Nečistý duch člověkem zalomcoval, hlasitě vykřikl a vyšel z něho."],[27,"Všichni užasli a ptali se jeden druhého: „Co to je? Jaké nové učení! S mocí přikazuje i nečistým duchům a oni ho poslouchají.“"],[28,"Zpráva o něm se rychle rozšířila po celém okolí Galileje."]]},{"title":"Uzdravení Petrovy tchyně a dalších nemocných","range":"Mk 1,29–34","thoughts":[],"verses":[[29,"Jakmile vyšli ze synagogy, šli s Jakubem a Janem do domu Šimona a Ondřeje."],[30,"Šimonova tchyně ležela v horečce a hned mu o ní řekli."],[31,"Ježíš k ní přistoupil, vzal ji za ruku a pozvedl ji. Horečka ji opustila a ona jim začala sloužit."],[32,"Večer po západu slunce k němu přiváděli všechny nemocné a posedlé."],[33,"Celé město se shromáždilo přede dveřmi."],[34,"Uzdravil mnoho lidí trpících různými nemocemi a vyhnal mnoho démonů. Démonům nedovoloval mluvit, protože věděli, kdo je."]]},{"title":"Ježíš káže po Galileji","range":"Mk 1,35–39","thoughts":[],"verses":[[35,"Časně ráno, ještě za tmy, Ježíš vstal, vyšel ven a odešel na opuštěné místo, kde se modlil."],[36,"Šimon a ti, kdo byli s ním, ho začali hledat."],[37,"Když ho našli, řekli mu: „Všichni tě hledají.“"],[38,"Ježíš jim odpověděl: „Pojďme jinam, do okolních městeček, abych kázal i tam. Proto jsem přišel.“"],[39,"A kázal v jejich synagogách po celé Galileji a vyháněl démony."]]},{"title":"Očištění malomocného","range":"Mk 1,40–45","thoughts":[],"verses":[[40,"Přišel k němu malomocný, prosil ho, klekl před ním a řekl: „Chceš-li, můžeš mě očistit.“"],[41,"Ježíš se nad ním slitoval, vztáhl ruku, dotkl se ho a řekl: „Chci. Buď čistý.“"],[42,"Jakmile to řekl, malomocenství od něho odešlo a byl očištěn."],[43,"Ježíš ho přísně napomenul a hned ho poslal pryč."],[44,"Řekl mu: „Dávej pozor, nikomu nic neříkej. Jdi, ukaž se knězi a za své očištění přines oběť, kterou přikázal Mojžíš, na svědectví pro ně.“"],[45,"On však odešel a začal o tom všude mnoho mluvit a zprávu šířit. Ježíš už proto nemohl veřejně vstoupit do města a zůstával venku na opuštěných místech. Lidé k němu přicházeli ze všech stran."]]}]};

MARK_SECTIONS["2"] = [{"title":"Uzdravení ochrnutého","range":"Mk 2,1–12","thoughts":[],"verses":[[1,"Po několika dnech Ježíš znovu přišel do Kafarnaum a rozneslo se, že je doma."],[2,"Shromáždilo se tolik lidí, že se nevešli ani přede dveře. Ježíš jim hlásal slovo."],[3,"Přišli k němu čtyři muži a nesli ochrnutého."],[4,"Protože se kvůli zástupu nemohli k Ježíšovi dostat, odkryli nad místem, kde byl, střechu. Udělali otvor a spustili dolů lůžko, na kterém ochrnutý ležel."],[5,"Když Ježíš viděl jejich víru, řekl ochrnutému: „Synu, tvé hříchy jsou ti odpuštěny.“"],[6,"Seděli tam někteří učitelé Zákona a ve svých srdcích uvažovali:"],[7,"„Jak může takhle mluvit? Rouhá se. Kdo může odpouštět hříchy kromě samotného Boha?“"],[8,"Ježíš ve svém duchu hned poznal, že takto uvažují, a řekl jim: „Proč o tom ve svých srdcích přemýšlíte?“"],[9,"„Co je snazší říct ochrnutému: Tvé hříchy jsou ti odpuštěny, nebo: Vstaň, vezmi své lůžko a choď?“"],[10,"„Abyste však věděli, že Syn člověka má na zemi moc odpouštět hříchy“ — řekl ochrnutému —"],[11,"„tobě říkám: Vstaň, vezmi své lůžko a jdi domů.“"],[12,"On hned vstal, vzal lůžko a přede všemi odešel. Všichni žasli, oslavovali Boha a říkali: „Něco takového jsme ještě nikdy neviděli.“"]]},{"title":"Povolání Léviho","range":"Mk 2,13–17","thoughts":[],"verses":[[13,"Ježíš znovu vyšel k jezeru. Přicházel k němu celý zástup a on je učil."],[14,"Když šel dál, uviděl Léviho, syna Alfeova, sedět v celnici a řekl mu: „Následuj mě.“ On vstal a následoval ho."],[15,"Když potom Ježíš stoloval v jeho domě, sedělo s ním a s jeho učedníky také mnoho celníků a hříšníků, protože jich bylo mnoho a následovali ho."],[16,"Když učitelé Zákona a farizeové viděli, že jí s celníky a hříšníky, ptali se jeho učedníků: „Proč jí a pije s celníky a hříšníky?“"],[17,"Ježíš to uslyšel a řekl jim: „Lékaře nepotřebují zdraví, ale nemocní. Nepřišel jsem volat spravedlivé, ale hříšníky k pokání.“"]]},{"title":"Otázka půstu","range":"Mk 2,18–22","thoughts":[],"verses":[[18,"Janovi učedníci a farizeové se postili. Přišli tedy k Ježíšovi a zeptali se: „Proč se Janovi učedníci a učedníci farizeů postí, ale tvoji učedníci se nepostí?“"],[19,"Ježíš jim řekl: „Mohou se svatební hosté postit, dokud je ženich s nimi? Dokud mají ženicha mezi sebou, nemohou se postit.“"],[20,"„Přijdou však dny, kdy jim bude ženich vzat. Tehdy se budou postit.“"],[21,"„Nikdo nepřišívá záplatu z nové látky na starý oděv. Jinak nová záplata odtrhne kus staré látky a trhlina se ještě zvětší.“"],[22,"„A nikdo nelije nové víno do starých měchů. Jinak nové víno měchy roztrhne, víno vyteče a měchy se zničí. Nové víno se musí lít do nových měchů.“"]]},{"title":"Ježíš je Pánem soboty","range":"Mk 2,23–28","thoughts":[],"verses":[[23,"Jednou Ježíš procházel v sobotu obilím. Jeho učedníci cestou začali trhat klasy."],[24,"Farizeové mu řekli: „Podívej, proč dělají v sobotu něco, co není dovoleno?“"],[25,"Ježíš jim odpověděl: „Nikdy jste nečetli, co udělal David, když byl v nouzi a měl hlad on i ti, kdo byli s ním?“"],[26,"„Jak za velekněze Abiatara vešel do Božího domu, jedl posvátné chleby, které směli jíst jen kněží, a dal i těm, kdo byli s ním?“"],[27,"Potom jim řekl: „Sobota byla učiněna pro člověka, ne člověk pro sobotu.“"],[28,"„Proto je Syn člověka Pánem i nad sobotou.“"]]}];

MARK_SECTIONS["3"] = [{"title":"Uzdravení člověka s ochrnutou rukou","range":"Mk 3,1–6","thoughts":[],"verses":[[1,"Ježíš znovu vešel do synagogy. Byl tam člověk s ochrnutou rukou."],[2,"Pozorovali Ježíše, zda ho v sobotu uzdraví, aby ho mohli obžalovat."],[3,"Řekl člověku s ochrnutou rukou: „Postav se doprostřed.“"],[4,"Potom se jich zeptal: „Je dovoleno v sobotu dělat dobře, nebo zle? Zachránit život, nebo zabít?“ Oni však mlčeli."],[5,"Ježíš se na ně rozhlédl s hněvem a zarmoutil se nad tvrdostí jejich srdce. Řekl tomu člověku: „Natáhni ruku.“ On ji natáhl a jeho ruka byla uzdravena."],[6,"Farizeové vyšli ven a hned se s Herodiány radili, jak by Ježíše zahubili."]]},{"title":"Zástupy u jezera","range":"Mk 3,7–12","thoughts":[],"verses":[[7,"Ježíš odešel se svými učedníky k jezeru a šel za ním veliký zástup z Galileje i z Judska,"],[8,"z Jeruzaléma, Idumey, Zajordání a z okolí Týru a Sidónu. Když lidé slyšeli, jak veliké věci dělá, přicházeli k němu ve velkém množství."],[9,"Ježíš řekl svým učedníkům, aby pro něj kvůli zástupu měli připravenou malou loď, aby ho lidé netlačili."],[10,"Mnohé totiž uzdravil, takže se na něj tlačili všichni, kdo trpěli nějakou nemocí, aby se ho mohli dotknout."],[11,"Kdykoli ho nečistí duchové uviděli, padali před ním a křičeli: „Ty jsi Boží Syn!“"],[12,"On jim však přísně přikazoval, aby ho neprozrazovali."]]},{"title":"Ježíš ustanovuje Dvanáct","range":"Mk 3,13–19","thoughts":[],"verses":[[13,"Ježíš vystoupil na horu a zavolal k sobě ty, které chtěl. A oni k němu přišli."],[14,"Ustanovil jich dvanáct, aby byli s ním, aby je posílal kázat"],[15,"a aby měli moc uzdravovat nemoci a vyhánět démony."],[16,"Šimona pojmenoval Petr;"],[17,"Jakuba, syna Zebedeova, a jeho bratra Jana pojmenoval Boanerges, to znamená Synové hromu;"],[18,"dále Ondřeje, Filipa, Bartoloměje, Matouše, Tomáše, Jakuba, syna Alfeova, Tadeáše, Šimona Kananejského"],[19,"a Jidáše Iškariotského, který ho později zradil. Potom vešli do domu."]]},{"title":"Ježíš a Belzebub","range":"Mk 3,20–30","thoughts":[],"verses":[[20,"Znovu se shromáždil zástup, takže se nemohli ani najíst."],[21,"Když o tom uslyšeli jeho příbuzní, vyšli, aby se ho zmocnili, protože říkali: „Pomátl se.“"],[22,"Učitelé Zákona, kteří přišli z Jeruzaléma, říkali: „Má Belzebuba“ a „Démony vyhání mocí vládce démonů.“"],[23,"Ježíš si je zavolal a mluvil k nim v podobenstvích: „Jak může satan vyhánět satana?“"],[24,"„Je-li království rozdělené samo proti sobě, nemůže takové království obstát.“"],[25,"„A je-li dům rozdělený sám proti sobě, nemůže takový dům obstát.“"],[26,"„Jestliže satan povstal sám proti sobě a je rozdělený, nemůže obstát, ale je s ním konec.“"],[27,"„Nikdo nemůže vejít do domu silného člověka a uloupit jeho věci, pokud toho silného nejprve nespoutá. Teprve potom může jeho dům vyplenit.“"],[28,"„Amen, říkám vám: Všechny hříchy budou lidským synům odpuštěny, i všechna rouhání, kterých se dopustí.“"],[29,"„Kdo by se však rouhal proti Duchu svatému, nemá odpuštění navěky, ale provinil se věčným hříchem.“"],[30,"Řekl to proto, že tvrdili: „Má nečistého ducha.“"]]},{"title":"Ježíšova pravá rodina","range":"Mk 3,31–35","thoughts":[],"verses":[[31,"Přišla jeho matka a jeho bratři. Zůstali venku a poslali pro něj."],[32,"Kolem něj seděl zástup a řekli mu: „Tvoje matka a tvoji bratři jsou venku a hledají tě.“"],[33,"Ježíš jim odpověděl: „Kdo je má matka a kdo jsou moji bratři?“"],[34,"Rozhlédl se po těch, kdo kolem něj seděli, a řekl: „Hle, má matka a moji bratři.“"],[35,"„Kdo plní Boží vůli, ten je můj bratr, má sestra i matka.“"]]}];
MARK_SECTIONS["4"] = [{"title":"Podobenství o rozsévači","range":"Mk 4,1–20","thoughts":[],"verses":[[1,"znovu počal učiti u moře. I shromáždil se k němu zástup mnohý, tak že vstoupiv na lodí, seděl na moři, a celý zástup byl na zemi podlé moře."],[2,"I učil je mnohým věcem v podobenstvích, a řekl jim v učení svém:"],[3,"Slyšte. Hle, vyšel rozsevač, aby rozsíval."],[4,"Stalo se v tom rozsívání, že jedno padlo podlé cesty, a přiletělo ptactvo nebeské, i zzobalo je."],[5,"jiné padlo na místo skalnaté, kdež nemělo mnoho země, a hned vzešlo, proto že nemělo hlubokosti země."],[6,"když vyšlo slunce, vyhořelo, a proto, že nemělo kořene, uschlo."],[7,"jiné padlo mezi trní; i zrostlo trní, a udusilo je. I nevydalo užitku."],[8,"Jiné pak padlo v zemi dobrou, a dalo užitek zhůru vstupující a rostoucí; přineslo zajisté jedno třidcátý, a jiné šedesátý, a jiné pak stý."],[9,"I řekl jim: Kdo má uši k slyšení, slyš."],[10,"Když pak byl sám, tázali se ho ti, kteříž při něm byli, se dvanácti, na to podobenství."],[11,"Řekl jim: Vámť je dáno, znáti tajemství království Božího, ale těm, kteříž jsou vně, v podobenství to všechno se děje,"],[12,"Aby hledíce, hleděli, ale neuzřeli a slyšíce, slyšeli, ale nesrozuměli, aby se snad neobrátili, a byli by jim odpuštěni hříchové."],[13,"I dí jim: Neznáte podobenství tohoto? A kterakž pak všechna podobenství poznáte?"],[14,"Rozsevač ten slovo rozsívá."],[15,"Tito pak jsou, ješto podlé cesty, jimž se rozsívá slovo, ale když oni slyší, i hned přichází satan, a vynímá slovo, kteréž vsáto je v srdcích jejich."],[16,"tak podobně ti, kteříž jako skalnatá země posáti jsou, kteříž jakž uslyší slovo, hned s radostí přijímají je."],[17,"Než nemají kořene v sobě, ale jsou časní; potom když vznikne ssoužení a protivenství pro slovo, hned se horší."],[18,"Tito pak jsou, kteříž mezi trní posáti jsou, ti jsou, kteříž slovo slyší,"],[19,"Však pečování tohoto světa a oklamání zboží, a jiné žádosti přistupující, udušují slovo, tak že bez užitku bývá."],[20,"Tito pak jsou, kteříž v zemi dobrou símě přijali, kteříž slyší slovo, a přijímají, a užitek přinášejí, jiné třidcátý, a jiné šedesátý, a jiné stý."]]},{"title":"Světlo se neschovává","range":"Mk 4,21–25","thoughts":[],"verses":[[21,"Dále řekl jim: Zdali rozsvícena bývá svíce, aby postavena byla pod nádobu neb pod postel? Však aby na svícen vstavena byla."],[22,"Protože nic není skrytého, co by nebylo zjeveno; aniž je co tak ukrytého, aby na jevo nevyšlo."],[23,"Jestliže kdo má uši k slyšení, slyš."],[24,"I mluvil k nim: Vizte, co slyšíte. Kterou měrou budete měřiti, bude vám odměřeno, a přidáno bude vám poslouchajícím."],[25,"Protože kdožť má, tomu bude dáno; a kdo nemá, i to, což má, bude od něj odjato."]]},{"title":"Podobenství o rostoucím semeni","range":"Mk 4,26–29","thoughts":[],"verses":[[26,"I řekl: Tak je království Boží, jako kdyby člověk uvrhl símě do země."],[27,"spal by, a vstával by ve dne i v noci a semeno by vzešlo a zrostlo, jakž on neví."],[28,"Protože sama od sebe země užitek plodí, nejprv bylinu, potom klas, potom plné obilé v klasu."],[29,"když sezrá úroda, i hned přičiní srp; nebo nastala žeň."]]},{"title":"Podobenství o hořčičném zrnu","range":"Mk 4,30–34","thoughts":[],"verses":[[30,"Řekl: K čemu připodobníme království Boží? Aneb kterým podobenstvím je ukážeme?"],[31,"Jest jako zrno horčičné, kteréž, když vsáto bývá do země, nejmenší je ze všech semen, kteráž jsou na zemi."],[32,"Ale když vsáto bývá, roste, a bývá větší než všechny byliny, a činí ratolesti veliké, tak že pod stínem jeho mohou sobě ptáci nebeští hnízda dělati."],[33,"takovými mnohými podobenstvími mluvil jim slovo, jakž mohli slyšeti."],[34,"Bez podobenství pak nemluvil jim, ale učedníkům svým soukromí vykládal všechno."]]},{"title":"Ježíš utišuje bouři","range":"Mk 4,35–41","thoughts":[],"verses":[[35,"Řekl jim v ten den, když již byl večer: Plavme se na druhou stranu."],[36,"nechavše zástupu, pojali ho, tak jakž byl na lodičce. Ale i jiné lodičky byly s ním."],[37,"Potom stala se bouře veliká od větru, až se vlny na lodí valily, tak že se již naplňovala lodí."],[38,"on z zadu na lodí spal na podušce. I zbudili ho, a řekli mu: Mistře, nedbáš, že hyneme?"],[39,"I probudiv se, přimluvil větru, a řekl moři: Umlkni, a upokoj se. I přestal vítr, a stalo se utišení veliké."],[40,"Řekl jim: Proč se tak bojíte? Jakž to, že nemáte víry?"],[41,"I báli se bázní velikou, a řekli jeden k druhému: I kdo je prosím tento, že i vítr i moře poslouchají jeho?"]]}];

MARK_SECTIONS["5"] = [{"title":"Uzdravení posedlého","range":"Mk 5,1–20","thoughts":[],"verses":[[1,"Potom přeplavili se přes moře do krajiny Gadarenských."],[2,"jakž vyšel z lodí, hned se s ním potkal člověk z hrobů, měl ducha nečistého."],[3,"Kterýž bydlil v hrobích, a aniž ho kdo mohl řetězy svázati,"],[4,"Proto že často když byl pouty a řetězy okován, polámal řetězy, a pouta roztrhal, a žádný nemohl ho skrotiti."],[5,"vždycky ve dne i v noci na horách a v hrobích byl, křiče a tepa se kamením."],[6,"Uzřev pak Ježíše zdaleka, běžel a poklonil se mu,"],[7,"křiče hlasem velikým, řekl: Co je tobě do mne, Ježíši, Synu Boha nejvyššího? Zaklínám tě skrze Boha, abys mne netrápil."],[8,"(Protože řekl mu: Vyjdiž, duchu nečistý, z člověka tohoto.)"],[9,"I otázal se ho: Jakť říkají? A on odpovídaje, řekl: Množství jméno mé je, nebo je nás mnoho."],[10,"I prosil ho velmi, aby jich nevyháněl z té krajiny."],[11,"Bylo pak tu při horách stádo vepřů veliké pasoucích se."],[12,"I prosili ho všichni ti ďáblové, řkouce: Pusť nás do vepřů, ať do nich vejdeme."],[13,"I povolil jim hned Ježíš. A vyšelše duchové nečistí, vešli do těch vepřů. I běželo to stádo s vrchu dolů do moře, (a bylo jich ke dvěma tisícům), i ztonuli v moři."],[14,"Ti pak, kteříž ty vepře pásli, utekli, a oznámili to v městě i ve vsech. I vyšli, aby viděli, co by to bylo, což se stalo."],[15,"Přišli k Ježíšovi, a uviděli toho, kterýž býval trápen od ďábelství, an sedí, odín když byl, a měl zdravý rozum, toho, kterýž míval množství. I báli se."],[16,"kteříž to viděli, vypravovali jim,kterak se stalo tomu, kterýž měl ďábelství i o vepřích."],[17,"Potom počali ho prositi, aby odšel z krajin jejich."],[18,"když vstoupil na lodí, prosil ho ten, kterýž trápen býval od ďábelství, aby s ním byl."],[19,"Ježíš pak nedopustil mu, ale řekl mu: Jdi k svým do domu svého, a zvěstuj jim, kterak veliké věci udělal tobě Pán, a že slitoval se nad tebou."],[20,"I odšel, a počal ohlašovati v krajině Desíti měst, kterak veliké věci udělal mu Ježíš. I divili se všichni."]]},{"title":"Jairova dcera a nemocná žena","range":"Mk 5,21–43","thoughts":[],"verses":[[21,"když se přeplavil Ježíš na lodí zase na druhou stranu, sšel se k němu zástup mnohý. A byl u moře."],[22,"aj, přišel jeden z knížat školy, jménem Jairus, a když uviděl ho, padl k nohám jeho."],[23,"velmi ho prosil, řka: Dcerka má skonává. Poď, vlož na ni ruce, aby uzdravena byla, a budeť živa."],[24,"Šel s ním, a zástup mnohý šel za ním, i tiskl ho."],[25,"(Potom žena jedna, kteráž tok krve měla dvanácte let,"],[26,"mnoho byla trápena od mnohých lékařů, a vynaložila celý statek svůj, a nic jí bylo neprospělo, ale vždy se hůře měla,"],[27,"Uslyšavši o Ježíšovi, přišla v zástupu po zadu, a dotkla se oděvy jeho."],[28,"Protože řekla byla: Dotknu-li se jen oděvy jeho, uzdravena budu."],[29,"hned přestal krvotok hoí, a pocítila na těle, že by uzdravena byla od neduhu svého."],[30,"hned Ježíš poznav sám v sobě, že z něj moc vyšla, obrátiv se v zástupu, řekl: Kdo se dotekl oděvy mého?"],[31,"I řekli mu učedníci jeho: Vidíš, že tě zástup tiskne, a pravíš: Kdo se mne dotekl?"],[32,"I hleděl kolem, aby ji uviděl, která to učinila."],[33,"Ta pak žena s bázní a s třesením, věduci, co se stalo při ní, přistoupila a padla před ním, a pověděla mu všecku pravdu."],[34,"On pak řekl jí: Dcero, víra tvá tě uzdravila, jdiž u pokoji, a buď zproštěna od trápení svého.)"],[35,"když on ještě mluvil, přišli z domu knížete školy, řkouce: Dcera tvá umřela, proč již zaměstknáváš Mistra?"],[36,"Ježíš pak, hned jakž uslyšel to, což oni mluvili, řekl knížeti školy: Neboj se, jen věř."],[37,"I nedal žádnému za sebou jíti, jediné Petrovi, Jakubovi a Janovi, bratru Jakubovu."],[38,"Přišel do domu knížete školy, a viděl tam hluk, ano plačí a kvílí velmi."],[39,"Když vešel tam, řekl jim: Co se bouříte a plačete? Neumřelať děvečka, ale spí."],[40,"I posmívali se mu. On pak vyhnav všechny, pojal otce a matku děvečky, a ty, kteříž s ním byli, i všel tam, kdež děvečka ležela."],[41,"vzav ruku děvečky, řekl jí: Talitha kumi. Což se vykládá: Děvečko, (toběť říkám), vstaň."],[42,"hned vstala děvečka, a chodila; nebo byla ve dvanácti letech. I zděsili se divením převelikým."],[43,"přikázal jim pilně, aby žádný o tom nezvěděl. I rozkázal jí dáti jísti."]]}];

MARK_SECTIONS["6"] = [{"title":"Ježíš v Nazaretě","range":"Mk 6,1–6","thoughts":[],"verses":[[1,"I vyšel odtud a přišel do vlasti své, a šli za ním učedníci jeho."],[2,"když bylo v sobotu, počal učiti v škole, a mnozí slyšíce, děsili se, řkouce: Odkud tento má tyto věci? A jaká je to moudrost, kteráž je dána mu, že i takové moci dějí se skrze ruce jeho?"],[3,"Zdaliž tento není ten tesař, syn Marie, bratr pak Jakubův a Jozesův a Judův a Šimonův? A zdaž nejsou i sestry jeho zde u nás? I horšili se na něm."],[4,"Řekl jim Ježíš: Není prorok beze cti, jediné v vlasti své a v rodině své a v domě svém."],[5,"I nemohl tu divu žádného udělat, jediné málo nemocných, vzkládaje na ně ruce, uzdravil."],[6,"I podivil se jejich nevěře, a obcházel kolem po městečkách, uče."]]},{"title":"Vyslání Dvanácti","range":"Mk 6,7–13","thoughts":[],"verses":[[7,"svolav k sobě těch dvanácte, počal je posílati po dvou a dvou, a dal jim moc nad duchy nečistými."],[8,"přikázal jim, aby ničeho nebrali na cestu, jediné jen hůl, ani mošny, ani chleba, ani do opasku peněz,"],[9,"Ale aby obuté měli nohy v střevíce, a neobláčeli dvou sukní."],[10,"řekl jim: Kdežkoli vešli byste do domu, tu ostaňte, dokudž nevyšli byste odtud."],[11,"kdož by koli vás nepřijali, ani vás neposlouchali, vyjdouce odtud, vyrazte prach z noh svých na svědectví jim. Amen, říkám vám: Lehčeji bude Sodomským a Gomorským v den soudný než městu tomu."],[12,"Potom vyšelše, kázali, aby pokání činili."],[13,"ďábelství mnohá vymítali, a mazali olejem mnohé nemocné, i uzdravovali."]]},{"title":"Smrt Jana Křtitele","range":"Mk 6,14–29","thoughts":[],"verses":[[14,"uslyšev o tom Heródes král, (nebo zjevné učiněno bylo jméno jeho), řekl, že Jan Křtitel vstal z mrtvých, a protož divové dějí se skrze něj."],[15,"Jiní pak řekli, že je Eliáš; a jiní řekli, že je prorok, aneb jako jeden z těch proroků."],[16,"To uslyšev Heródes, řekl: Totoť je ten Jan, kteréhož jsem já sťal. Ontě z mrtvých vstal."],[17,"Ten zajisté Heródes poslav, jal Jana, a vsadil ho do žaláře pro Herodiadu manželku Filipa bratra svého, že ji byl za manželku pojal."],[18,"Protože řekl Jan Heródesovi: Neslušíť tobě míti manželky bratra svého."],[19,"Herodias pak lest skládala proti němu, a chtěla ho o hrdlo připraviti, ale nemohla."],[20,"Protože Heródes ostýchal se Jana, věda ho býti muže spravedlivého a svatého. I šetřil ho, a slýchaje ho, mnoho i činil, a rád ho poslouchal."],[21,"Když pak přišel den příhodný, v němž Heródes, pamatuje den svého narození, udělal večeři knížatům svým a hejtmanům a předním mužům z Galilee,"],[22,"když dcera té Herodiady tam vešla a tancovala, a zalíbila se Heródesovi i spoluhodovníkům, řekl král děvečce: Pros mne, zač chceš, a dámť."],[23,"I přisáhl jí: Že začkoli prositi budeš, dám tobě, by pak bylo až do polovice království mého."],[24,"Ona pak vyšelši, řekla mateři své:Zač budu prositi? A ona řekla: Za hlavu Jana Křtitele."],[25,"vešelši hned s chvátaním k králi, prosila, řkuci: Chci, abys mi dal hned na mise hlavu Jana Křtitele."],[26,"Král pak zarmoutiv se velmi, pro přísahu a pro spoluhodovníky nechtěl jí oslyšeti."],[27,"Protož král ten poslav hned kata, rozkázal přinesti hlavu Janovu."],[28,"on odšel, sťal ho v žaláři, a přinesl hlavu jeho na mise, a dal ji děvečce, a děvečka dala ji mateři své."],[29,"Potom uslyševše to učedníci jeho, přišli, a vzali tělo jeho, a pochovali je v hrobě."]]},{"title":"Návrat apoštolů a nasycení pěti tisíc","range":"Mk 6,30–44","thoughts":[],"verses":[[30,"Tehdy sšelše se apoštolé k Ježíšovi, zvěstovali mu všechno, i to, co činili, i co učili."],[31,"Řekl jim: Pojďte vy sami obzvláštně na pusté místo, a odpočiňte maličko. Protože bylo množství těch, kteříž přicházeli a odcházeli, tak že ani k jídlu chvíle neměli."],[32,"I plavili se na lodí na pusté místo soukromí."],[33,"vidouce je zástupové, že jdou pryč, poznali ho mnozí. I zběhli se tam ze všech měst pěšky, a předešli je, a shromáždili se k němu."],[34,"Potom vyšel Ježíš, uviděl zástup mnohý, a slitovalo mu se jich, že byli jako ovce, nemajíce pastýře. I počal je učiti mnohým věcem."],[35,"když se již prodlilo, přistoupilše k němu učedníci jeho, řekli: Pustéť je toto místo, a již se prodlilo."],[36,"Propusť je, ať když šli do okolních vesnic a městeček, nakoupí sobě chleba; nebo nemají, co by jedli."],[37,"On pak odpověděl, řekl jim: Dejte vy jim jísti. I řkou mu: Jdouce, koupíme za dvě stě grošů chleba, a dáme jim jísti?"],[38,"I dí jim: Kolik chlebů máte? Jděte a zvězte. A když zvěděli, řekli: Pět, a dvě rybě."],[39,"I rozkázal jim, aby se kázali posaditi všechněm po houfích na zelené trávě."],[40,"I usadili se rozdílně, po stu a po padesáti."],[41,"vzav těch pět chlebů a ty dvě rybě, popatřiv do nebe, dobrořečil, i lámal chleby, a dal učedníkům svým, aby kladli před ně. A dvě rybě rozdělil mezi všechny."],[42,"I jedli všichni, a nasyceni jsou."],[43,"Potom sebrali drobtů dvanácte košů plných, i z ryb."],[44,"bylo těch, kteříž jedli ty chleby, okolo pěti tisíců mužů."]]},{"title":"Ježíš kráčí po vodě","range":"Mk 6,45–52","thoughts":[],"verses":[[45,"hned přinutil učedlníky své, aby vstoupili na lodí, a předešli ho přes moře k Betsaidě, až by on propustil zástup."],[46,"propustiv je, šel na horu, aby se modlil."],[47,"když byl večer, byla lodí u prostřed moře, a on sám na zemi."],[48,"viděl je, a oni se s těžkostí plavili; (nebo byl vítr odporný jim). A při čtvrtém bdění nočním přišel k nim, chodě po moři, a chtěl jich pominouti."],[49,"Oni pak když uvidělše ho, an chodí po moři, domnívali se, že by obluda byla. I zkřikli."],[50,"(Protože ho všichni viděli, a zstrašili se.) Ale hned promluvil k nim a řekl jim: Doufejtež, jáť jsem, nebojte se."],[51,"I vstoupil k nim na lodí, a utišil se vítr; a oni mnohem více sami v sobě se děsili a divili."],[52,"Protože nerozuměli z strany chlebů; bylo zajisté srdce jejich zhrublo."]]},{"title":"Uzdravování v Genezaretu","range":"Mk 6,53–56","thoughts":[],"verses":[[53,"přeplavivše se, přišli do země Genezaretské, a tu lodí přistavili."],[54,"když vyšli z lodí, hned ho poznali."],[55,"běhajíce po vší krajině té, počali na ložcích nositi nemocné, kdežkoli uslyšeli o něm, že by byl."],[56,"kamžkoli vcházel do městeček neb do měst neb do vsí, na ulicech kladli neduživé, a prosili ho, aby se aspoň podolka oděvy jeho dotkli. A kolikož jich koli se jeho dotklo, uzdraveni byli."]]}];

MARK_SECTIONS["7"] = [{"title":"Co člověka znečišťuje","range":"Mk 7,1–23","thoughts":[],"verses":[[1,"I sešli se k němu farizeové a někteří z zákonníků, kteříž byli přišli z Jeruzaléma."],[2,"když uvidělše některé z učedníků jeho obecnýma rukama, (to je neumytýma), jísti chleby, reptali o to."],[3,"Protože farizeové i všichni Židé nejedí, leč by ruce umyli, držíce ustanovení starších."],[4,"po trhu nejedí, leč se umyjí. A jiné mnohé věci jsou, kteréž přijali, aby je zachovávali, jako umývání koflíků, žejdlíků a medenic i stolů."],[5,"Potom otázali se ho farizeové a zákonníci: Proč učedníci tvoji nezachovávají ustanovení starších, ale neumytýma rukama jedí chléb?"],[6,"On pak odpověděl, řekl jim: Dobře prorokoval Izaiáš o vás pokrytcích, jakož psáno je: Lid tento rty mne ctí, srdce pak jejich daleko je ode mne."],[7,"Ale nadarmoť mne ctí, učíce učení a ustanovení lidská."],[8,"Protože opustivše přikázaní Boží, držíte ustanovení lidská, umývání žejdlíků a koflíků, a jiné věci mnohé těm podobné činíte."],[9,"I řekl jim: Čistě vy rušíte přikázaní Boží, abyste ustanovení svá zachovali."],[10,"Protože Mojžíš pověděl: Cti otce svého i matku svou, a kdož by zlořečil otci neb mateři, ať smrtí umře."],[11,"Ale vy říkáte: Řekl-li by člověk otci neb mateři: Korban, (totiž, dar je to), čímž by tobě ode mne pomoženo býti mohlo."],[12,"nedopustíte mu nic více udělat otci svému neb mateři své,"],[13,"Rušíce slovo Boží ustanovením svým, kteréž jste ustanovili. A mnohé těm podobné věci činíte."],[14,"I svolav celý zástup, řekl jim: Slyšte mne všichni a rozumějte."],[15,"Nic není z zevnitřku vcházejícího do člověka, což by ho poškvrniti mohlo; ale to, což pochází z něj, toť je, což poškvrňuje člověka."],[16,"Má-li kdo uši k slyšení, slyš."],[17,"když všel do domu od zástupu, tázali se ho učedníci jeho o tom podobenství."],[18,"Řekl jim: Tak jste i vy nerozumní? Což nerozumíte, že všechno, což z zevnitřku do člověka vchází, nemůže ho poškvrniti?"],[19,"Protože nevchází v srdce jeho, ale v břicho, a potom ven vychází, čistěci všeliké pokrmy."],[20,"Pravil pak, že to, což pochází z člověka, to poškvrňuje člověka."],[21,"Protože z vnitřku z srdce lidského zlá myšlení pocházejí, cizoložstva, smilstva, vraždy,"],[22,"Krádeže, lakomství, nešlechetnosti, lest, nestydatost, oko zlé, rouhání, pýcha, bláznovství."],[23,"Všecky tyto zlé věci pocházejí z vnitřku, a poškvrňují člověka."]]},{"title":"Víra syrofénické ženy","range":"Mk 7,24–30","thoughts":[],"verses":[[24,"vstal odtud, odšel do končin Týru a Sidonu, a vešel do domu, nechtěl, aby kdo věděl, ale nemohl se tajiti."],[25,"Protože uslyševši o něm žena, hoíž dcerka měla ducha nečistého, přišla a padla k nohám jeho."],[26,"(Byla pak ta žena pohanka, Syrofenitská rodem.) I prosila ho, aby ďábelství vyvrhl z hoí dcery."],[27,"Ale Ježíš řekl jí: Nechať se prvé nasytí řekltky; nebť není slušné vzíti chléb dětem a vrci štěňatům."],[28,"ona odpověděla a řekla mu: Ovšem, Pane, nebo štěňátka jedí pod stolem drobty synů."],[29,"Řekl jí: Pro tu řeč jdi, vyšloť je ďábelství z tvé dcery."],[30,"I odšelši do domu svého, nalezla děvečku, ana leží na loži, a ďábelství z ní vyšlo."]]},{"title":"Uzdravení hluchoněmého","range":"Mk 7,31–37","thoughts":[],"verses":[[31,"Potom vyšel zase z končin Tyrských a Sidonských, přišel k moři Galilejskému, prostředkem krajin Desíti měst."],[32,"I přivedli mu hluchého a zajikavého, a prosili ho, aby na něj ruku vzložil."],[33,"pojav ho soukromí ven z zástupu, vložil prsty své v uši jeho, a plinuv, dotekl se jazyka jeho."],[34,"vzezřev k nebi, vzdechl a řekl mu: Efata, to je, otevři se."],[35,"hned otevříny jsou uši jeho, a rozvázán je svazek jazyka jeho, i mluvil právě."],[36,"I přikázal jim, aby žádnému nepravili. Ale jakkoli on jim přikazoval, oni mnohem více ohlašovali."],[37,"převelmi se divili, řkouce: Dobře všechny věci udělal. I hluchým rozkázal slyšeti, i němým mluviti."]]}];

MARK_SECTIONS["8"] = [{"title":"Nasycení čtyř tisíc","range":"Mk 8,1–10","thoughts":[],"verses":[[1,"V těch dnech když velmi veliký zástup byl, a neměli, co by jedli, svolav"],[2,"Lítost mám nad zástupy; nebo již tři dni trvají se mnou, a nemají, co by jedli."],[3,"rozpustím-li je lačné do domů jejich, zhynou na cestě; nebo někteří z nich zdaleka přišli."],[4,"Odpověděli mu učedníci jeho: I odkud bude moci kdo tyto nakrmiti chleby zde na poušti?"],[5,"I otázal se jich: Kolik máte chlebů? A oni řekli: Sedm."],[6,"I kázal zástupu posaditi se na zemi. A vzav těch sedm chlebů, řeklky učiniv, lámal a dával učedníkům svým, aby předkládali. I kladli před zástup."],[7,"měli rybiček maličko. Jichž požehnav, kázal i ty před ně klásti."],[8,"I jedli a nasyceni jsou; a sebrali, což pozůstalo drobtů, sedm košů."],[9,"Těch pak, kteříž jedli, bylo okolo čtyř tisíců. I propustil je."],[10,"Potom hned vstoupiv na lodí s učedlníky svými, přeplavil se do krajin Dalmanutských."]]},{"title":"Farizeové žádají znamení","range":"Mk 8,11–13","thoughts":[],"verses":[[11,"I vyšli farizeové, a počali se s ním hádati, hledajíce od něj znamení s nebe, pokoušejíce ho."],[12,"on vzdech duchem svým, dí: Co pokolení toto znamení hledá? Amen, říkám vám: Nebude dáno znamení pokolení tomuto."],[13,"opustiv je, vstoupil zase na lodí, i plavil se dále."]]},{"title":"Varování před kvasem","range":"Mk 8,14–21","thoughts":[],"verses":[[14,"I zapomenuli s sebou vzíti chlebů, a neměli než jeden chléb s sebou na lodí."],[15,"Potom přikazoval jim, řka: Vizte a pilně se šetřte kvasu farizejského a kvasu Heródesova."],[16,"I přemyšlovali, řkouce jeden k druhému: Chleba nemáme."],[17,"znaje to Ježíš, řekl jim: Co přemyšlujete o tom, že chleba nemáte? Ještě neznáte, ani nerozumíte? Ještě máte oslepené své srdce?"],[18,"Oči měli, nevidíte? A uši měli, neslyšíte? A nepomníte,"],[19,"Že jsem pět chlebů lámal mezi pět tisíců? Kolik jste plných košů drobtů sebrali? Řekli mu: Dvanácte."],[20,"když také sedm chlebů mezi čtyři tisíce, kolik jste plných košů drobtů vzali? I řkou mu: Sedm."],[21,"Řekl jim: Kterakž nerozumíte?"]]},{"title":"Uzdravení slepého v Betsaidě","range":"Mk 8,22–26","thoughts":[],"verses":[[22,"Přišel do Betsaidy, a přivedli k němu slepého, prosíce ho, aby se ho dotekl."],[23,"I ujav toho slepého za ruku, vyvedl ho ven z městečka, a plinuv na oči jeho, a vloživ na něj ruce, otázal se ho, viděl-li by co."],[24,"on pohleděv zhůru, řekl: Znamenám lidi; nebo vidím, že chodí jako stromové."],[25,"Potom znovu vložil ruce na oči jeho, a kázal mu hleděti zhůru. I uzdraven je, tak že i zdaleka jasně viděl všechny."],[26,"I odeslal ho do domu jeho, řka: Aniž do toho městečka choď, aniž komu z městečka prav."]]},{"title":"Petrovo vyznání","range":"Mk 8,27–30","thoughts":[],"verses":[[27,"Potom vyšel Ježíš a učedníci jeho do městeček Cesaree Filipovy. A na cestě tázal se učedníků svých, řka jim: Kým mne praví býti lidé?"],[28,"Kteříž odpověděli: Janem Křtitelem, a jiní Eliášem, jiní pak jedním z proroků."],[29,"Potom on řekl jim: Vy pak kým mne býti říkáte? Odpověděv Petr, řekl mu: Ty jsi Kristus."],[30,"I přikázal jim s pohrůžkou, aby o něm žádnému nepravili."]]},{"title":"První předpověď utrpení","range":"Mk 8,31–33","thoughts":[],"verses":[[31,"I počal učiti je, že Syn člověka musí mnoho trpěti, a potupen býti od starších a předních kněží {biskupů} a zákonníků, a zabit býti, a ve třech dnech z mrtvých vstáti."],[32,"zjevně to slovo mluvil. Protož chytiv ho Petr, počal mu domlouvati."],[33,"Kterýžto obrátiv se, a pohleděv na učedlníky své, přimluvil Petrovi, řka: Jdiž za mnou, satane; nebo nechápáš, co je Božího, ale co lidského."]]},{"title":"Následování Ježíše","range":"Mk 8,34–38","thoughts":[],"verses":[[34,"svolav zástup s učedlníky svými, řekl jim: Chce-li kdo za mnou přijíti, zapři sebe sám, a vezmi kříž svůj, a následuj mne."],[35,"Protože chtěl-li by kdo duši svou zachovati, ztratíť ji; pakli by kdo ztratil duši svou pro mne a pro evangelium, tenť ji zachová."],[36,"Protože co prospěje člověku, by celý svět získal, a své duši škodu udělal?"],[37,"Aneb jakou dá člověk odměnu za duši svou?"],[38,"Protože kdož by se koli za mne styděl a za má slova v tomto pokolení cizoložném a hříšném, i Syn člověka styděti se bude za něj, když přijde v slávě Otce svého s anděly svatými."]]}];

MARK_SECTIONS["9"] = [{"title":"Proměnění na hoře","range":"Mk 9,1–13","thoughts":[],"verses":[[1,"I řekl jim: Amen, říkám vám, žeť jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří království Boží přicházející v moci."],[2,"po šesti dnech pojal Ježíš Petra a Jakuba a Jana, i uvedl je na horu vysokou soukromí samy, a proměnil se před nimi."],[3,"učiněno je oděv jeho stkvoucí a bílé velmi jako sníh, ješto tak bílého bělič na zemi udělat nemůže."],[4,"I uviděli Eliáše s Mojžíšem, ani s Ježíšem mluví."],[5,"odpověděl Petr, řekl Ježíšovi: Mistře, dobréť je nám tuto býti. Protož udělejme tři stánky, tobě jeden, Mojžíšovi jeden, a Eliášovi jeden."],[6,"Protože nevěděl, co mluví; byli zajisté přestrašeni."],[7,"I stal se oblak zastěňující je, a přišel hlas z oblaku, řkoucí: Tentoť je ten Syn můj milý, jeho poslouchejte."],[8,"hned obezřevše se, žádného víc neviděli než samého Ježíše s sebou."],[9,"když sstupovali s hory, přikázal jim, aby toho žádnému nevypravovali, co viděli, než až Syn člověka z mrtvých vstane."],[10,"I zachovali tu věc u sebe, tížíce mezi sebou, co by to bylo z mrtvých vstáti."],[11,"I otázali se ho, řkouce: Což to pak zákonníci praví, že Eliáš musí přijíti prvé?"],[12,"On pak odpověděl, řekl jim: Eliáš přijda nejprvé, napraví všechny věci, a jakož psáno je o Synu člověka, že musí mnoho trpěti, a za nic položen býti."],[13,"Ale říkám vám, že i Eliáš přišel, i udělali mu, což chtěli, jakož psáno je o něm."]]},{"title":"Uzdravení chlapce s nečistým duchem","range":"Mk 9,14–29","thoughts":[],"verses":[[14,"Potom když přišel k učedníkům, uviděl zástup veliký okolo nich, a zákonníky, an se hádají s nimi."],[15,"hned celý zástup když uviděl ho, ulekli se; a zběhše se, přivítali ho."],[16,"I otázal se zákonníků: Co se hádáte spolu?"],[17,"odpovídaje jeden z zástupu, řekl: Mistře, přivedl jsem syna svého k tobě, kterýž má ducha němého."],[18,"Ten kdyžkoli ho pochopí, lomcuje jím, a on se sliní, a škřipí zubami svými, a svadne. Řekl jsem učedníkům tvým, aby ho vyvrhli, ale nemohli."],[19,"on odpovídaje mu, řekl: Ó národe nevěrný. Ale dokudž s vámi budu? A dokudž vás trpěti budu? Přiveďte ho ke mně."],[20,"I přivedli ho k němu. A jakž ho uviděl, hned ním duch lomcoval; a padna na zemi, válel se a slinil."],[21,"I otázal se otce jeho: Dávno-li se mu to stalo? A on řekl: Od dětinství."],[22,"často jím metal i na oheň i do vody, aby ho zahubil. Ale můžeš-li co, spomoz nám, slituje se nad námi."],[23,"Ježíš řekl mu: Můžeš-li tomu věřiti; všechnoť je možné věřícímu."],[24,"i hned zvolav otec mládence toho s slzami, řekl: Věřím, Pane, spomoz nedověře mé."],[25,"Uzřev pak Ježíš, že se zbíhá zástup, přimluvil duchu tomu nečistému, řka mu: Duchu němý a hluchý, já tobě přikazuji, vyjdi z něj, a nevcházej více do něj."],[26,"Potom křiče a velmi jím lomcuje, vyšel. I učiněn je jako mrtvý, tak že mnozí řekli, že umřel."],[27,"Ale Ježíš ujav ho za ruku, pozdvihl ho. I vstal."],[28,"když všel do domu, učedníci jeho otázali se ho soukromí: Proč jsme my ho nemohli vyvrci?"],[29,"Řekl jim: Toto pokolení nijakž nemůž vyjíti, jediné skrze modlitbu a půst."]]},{"title":"Druhá předpověď utrpení","range":"Mk 9,30–32","thoughts":[],"verses":[[30,"když šli odtud, šli spolu skrze Galilei, ale nechtěl, aby kdo věděl."],[31,"Protože učil učedlníky své a řekl jim: Že Syn člověka dán bude v ruce lidské, a zamordujíť ho, ale zamordován když byl, třetího dne z mrtvých vstane."],[32,"Oni pak nesrozuměli tomu povědění, a však ostýchali se ho otázati."]]},{"title":"Kdo je největší","range":"Mk 9,33–37","thoughts":[],"verses":[[33,"Přišel do Kafarnaum, a v domě když byl, otázal se jich: Co jste na cestě mezi sebou rozjímali?"],[34,"Ale oni mlčeli. Protože hádali se byli na cestě mezi sebou, kdo by z nich byl větší."],[35,"posadiv se, zavolal dvanácti, a dí jim: Chce-li kdo první býti, budeť ze všech nejposlednější a všech služebník."],[36,"vzav pacholátko, postavil je u prostřed nich, a vzav je na lokty, řekl jim:"],[37,"Kdož by koli jedno z takových pacholátek přijal ve jménu mém, mneť přijímá; a kdož by mne koli přijal, ne mneť přijímá, ale toho, kterýž mne poslal."]]},{"title":"Kdo není proti nám, je s námi","range":"Mk 9,38–41","thoughts":[],"verses":[[38,"I odpověděl mu Jan, řka: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá, kterýž nechodí s námi; i bránili jsme mu, proto že s námi nechodí."],[39,"Ježíš pak řekl: Nebraňtež mu. Protožeť není žádného, kterýž by divy činil ve jménu mém, aby mohl snadně zle mluviti o mně."],[40,"Protože kdož není proti nám, s námiť je."],[41,"Kdož by koli zajisté dal vám píti číši vody ve jménu mém, proto že jste Kristovi, amen říkám vám, neztratíť ne odplaty své."]]},{"title":"Varování před sváděním k hříchu","range":"Mk 9,42–50","thoughts":[],"verses":[[42,"kdož by koli pohoršil jednoho z těchto maličkých, věřících ve mne, mnohem by mu lépe bylo, aby byl zavěšen na hrdlo jeho žernov mlýnský a vržen byl do moře."],[43,"horšila-li by tě ruka tvá, utni ji. Lépeť je tobě bezrukému vjíti do života, nežli obě ruce mělaímu jíti do pekla v ten oheň neuhasitelný,"],[44,"Kdež červ jejich neumírá, a oheň nehasne."],[45,"pakli noha tvá horšila by tě, utni ji. Lépeť je tobě kulhavému vjíti do života,nežli obě noze mělaímu uvrženu býti do pekla, v ten oheň neuhasitelný,"],[46,"Kdež červ jejich neumírá, a oheň nehasne."],[47,"Pakli by tě oko tvé horšilo, vylup je. Lépeť je tobě jednookému vjíti do království Božího, nežli obě oči mělaímu uvrženu býti do ohně pekelného,"],[48,"Kdež červ jejich neumírá, a oheň nehasne."],[49,"Protože každý ohněm bude solen, a všeliká obět solí bude osolena."],[50,"Dobráť je sůl. Pakli sůl bude neslaná, čím ji osolíte? Mějte sůl sami v sobě, a pokoj mějte mezi sebou."]]}];

MARK_SECTIONS["10"] = [{"title":"Manželství a rozvod","range":"Mk 10,1–12","thoughts":[],"verses":[[1,"vstal odtud, přišel do končin Judských skrze krajinu za Jordánem ležící. I sešli se k němu zase zástupové, a jakž obyčej měl, znovu je učil."],[2,"Potom přistoupilše farizeové, otázali se ho: sluší-li muži propustiti ženu? pokoušejíce ho."],[3,"On pak odpovídaje, řekl jim: Co vám přikázal Mojžíš?"],[4,"Kteříž řekli: Mojžíš dopustil lístek rozloučení napsati a propustiti."],[5,"I odpověděl Ježíš, řekl jim: Pro tvrdost srdce vašeho napsal vám to přikázaní."],[6,"Ale od počátku stvoření muže a ženu udělal je Bůh."],[7,"Protoť opustí člověk otce svého i matku, a přídržeti se bude ženy své."],[8,"I budou ti dva jedno tělo. A tak již nejsou dva, ale jedno tělo."],[9,"Protož což Bůh spojil, člověk nerozlučuj."],[10,"v domě znovu učedníci jeho otázali se ho o též věci."],[11,"I dí jim: Kdož by koli propustil manželku svou a jinou pojal, cizoloží proti ní."],[12,"jestliže by žena propustila muže svého a za jiného se vdala, cizoloží."]]},{"title":"Ježíš a děti","range":"Mk 10,13–16","thoughts":[],"verses":[[13,"Potom přinášeli k němu řekltky, aby se jich dotýkal. Ale učedníci přimlouvali těm, kteříž je nesli."],[14,"To když viděl Ježíš, nelibě to nesl, a řekl jim: Nechte řekltek jíti ke mně, a nebraňte jim, nebo takovýchť je království Boží."],[15,"Amen, říkám vám: Kdož by koli nepřijal království Božího jako řekltě, neť do něj nevejde."],[16,"bera je na lokty své, a vzkládaje na ně ruce, požehnání jim dával."]]},{"title":"Bohatý muž","range":"Mk 10,17–31","thoughts":[],"verses":[[17,"Potom když vyšel na cestu, přiběhl jeden, a poklekna před ním, otázal se ho: Mistře dobrý, co učiním, abych života věčného dědičně došel?"],[18,"Řekl mu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný Bůh."],[19,"Přikázaní umíš: Nezcizoložíš, nezabiješ, neukradneš, nevydáš falešného svědectví, neoklamáž, cti otce svého i matku."],[20,"on odpověděl, řekl mu: Mistře, toho všeho jsem ostříhal od své mladosti."],[21,"Potom Ježíš pohleděv na něj, zamiloval ho, a řekl mu: Jednohoť se nedostává. Jdi, a cokoli máš, prodej, a dej chudým, a budeš míti poklad v nebi; a poď, následuj mne, vezma kříž."],[22,"On pak zarmoutiv se pro to slovo, odšel, truchliv když byl; nebo měl mnohá zboží."],[23,"pohleděv kolem Ježíš, dí učedníkům svým: Jak nesnadně ti, kteříž statky mají, vejdou do království Božího."],[24,"Potom učedníci užasli se nad těmi řečmi jeho. Ježíš pak zase odpověděl, dí jim: Synáčkové, kterak nesnadné je doufajícím v statek do království Božího vjíti."],[25,"Snáze je velbloudu skrze jehelní ucho projíti, nežli bohatému vjíti do království Božího."],[26,"Oni pak více se děsili, řkouce mezi sebou:I kdož může spasen býti?"],[27,"pohleděv na ně Ježíš, dí: U lidíť je nemožné, ale ne u Boha; nebo u Boha všechno možné je."],[28,"I počal Petr mluviti k němu: Hle, my opustili jsme všechno, a šli jsme za tebou."],[29,"Odpověděv pak Ježíš, řekl: Amen, říkám vám, žádného není, ješto by opustil dům, neb bratří, neb sestry, neb otce, neb matku, neb manželku, neb řekltky, neb rolí pro mne a pro evangelium,"],[30,"Aby nevzal stokrát tolik nyní v času tomto domů a bratrů a sester a matek a řekltek a rolí s pronásledováním, a v budoucím věku život věčný."],[31,"Mnozíť pak první budou poslední, a poslední první."]]},{"title":"Třetí předpověď utrpení","range":"Mk 10,32–34","thoughts":[],"verses":[[32,"Byli pak na cestě, když šli do Jeruzaléma, a Ježíš šel napřed. I byli předěšeni, a když šli za ním, báli se. Potom pojav znovu dvanácte, počal jim praviti, co se mu má státi,"],[33,"Řka: Hle, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím {biskupům} a zákonníkům i odsoudí ho na smrt, a vydadí ho pohanům."],[34,"Kteřížto posmívati se budou mu, a ubičují ho, a uplijí i zabijí ho, ale třetího dne z mrtvých vstane."]]},{"title":"Prosba Jakuba a Jana","range":"Mk 10,35–45","thoughts":[],"verses":[[35,"Potom přistoupili k němu Jakub a Jan, synové Zebedeovi, řkouce: Mistře, chceme, zač bychom koli prosili tebe, abys udělal nám."],[36,"On pak řekl jim: Co chcete, abych vám udělal?"],[37,"I řekli mu: Dej nám, abychom jeden na pravici tvé a druhý na levici tvé seděli v slávě tvé."],[38,"Ježíš pak řekl jim: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já piji, a křtíti se křtem, kterýmž já se křtím?"],[39,"oni řekli mu: Můžeme. Ježíš pak řekl jim: Kalich zajisté, kterýž já piji, píti budete, a křtem, kterýmž já se křtím, křtěni budete,"],[40,"Ale seděti na pravici mé neb na levici mé, neníť má věc dáti, ale kterýmž připraveno je."],[41,"uslyšavše to deset, počali se hněvati na Jakuba a na Jana."],[42,"Ale Ježíš povolav jich, řekl jim: Víte, že ti, kteříž sobě zalibují vládnouti nad národy, panujíť nad nimi; a kteříž velicí u nich jsou, moc provozují nad nimi."],[43,"Ne takť bude mezi vámi. Ale kdokoli chtěl by mezi vámi býti veliký, budiž váš služebník."],[44,"kdokoli z vás chtěl by býti přední, budiž služebník všech."],[45,"Protože i Syn člověka nepřišel, aby mu sloužili, ale aby sloužil, a aby dal duši svou na vykoupení za mnohé."]]},{"title":"Uzdravení slepého Bartimea","range":"Mk 10,46–52","thoughts":[],"verses":[[46,"Potom přišli do Jericho, a když vycházel on z Jericha, i učedníci jeho a zástup mnohý, Timeův syn, Bartimeus slepý, seděl podlé cesty, žebře."],[47,"když uslyšel, že by byl Ježíš Nazaretský, počal volati a říci: Ježíši, synu Davidův, smiluj se nade mnou."],[48,"I přimlouvali mu mnozí, aby mlčel. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou."],[49,"Potom zastaviv se Ježíš, kázal ho zavolati. I zavolali toho slepého, řkouce mu: Dobré mysli buď, vstaň, volá tě."],[50,"On pak povrh plášť svůj, a zchopiv se, šel k Ježíšovi."],[51,"I odpověděl Ježíš, dí mu: Co chceš, ať učiním? A slepý řekl mu: Mistře, ať vidím."],[52,"Potom Ježíš řekl mu: Jdi, víra tvá tě uzdravila. A hned prohlédl, a šel cestou za Ježíšem."]]}];

MARK_SECTIONS["11"] = [{"title":"Vjezd do Jeruzaléma","range":"Mk 11,1–11","thoughts":[],"verses":[[1,"když se přiblížili k Jeruzalému a Betfagi i Betany při hoře Olivetské, poslal dva z učedníků svých."],[2,"řekl jim: Jděte do městečka, kteréž proti vám je, a hned vejdouce tam, naleznete oslátko přivázané, na kterémž nižádný z lidí neseděl. Odvížíce, přiveďte."],[3,"řekl-liť by vám kdo: Co to činíte? rcete: Že ho Pán potřebuje. A hned je pošle sem."],[4,"I odešli, a nalezli oslátko přivázané vně u dveří na rozcestí. I odvázali je."],[5,"Potom někteří z těch, kteříž tu stáli, řekli jim: Co činíte, odvazujíce oslátko?"],[6,"Oni pak řekli jim, jakož byl přikázal Ježíš. I nechali jich."],[7,"Protož přivedli oslátko k Ježíšovi, a vložili na ně oděvy svá. I vsedl na ně."],[8,"Mnozí pak stlali oděvy svá na cestě, a jiní ratolesti sekali z stromů, a metali na cestu."],[9,"kteříž napřed šli, i ti, kteříž za ním šli, volali, řkouce: Hosanna. Požehnaný, kterýž se béře ve jménu Páně."],[10,"Požehnané království otce našeho Davida, kteréž přišlo ve jménu Páně. Hosanna na výsostech."],[11,"I všel do Jeruzaléma Ježíš, i do chrámu. A spatřiv tu všechno, když již byla večerní hodina, vyšel do Betany se dvanácti."]]},{"title":"Prokletí fíkovníku","range":"Mk 11,12–14","thoughts":[],"verses":[[12,"druhého dne, když vycházel z Betany, zlačněl."],[13,"když uviděl z daleka fík, an má lístí, šel, zda by co nalezl na něm. A když přišel k němu, nic nenalezl kromě lístí; nebo nebyl čas fíků."],[14,"Potom odpověděl Ježíš, řekl mu: Již více na věky nižádný z tebe ovoce nejez. A slyšeli to učedníci jeho."]]},{"title":"Vyčištění chrámu","range":"Mk 11,15–19","thoughts":[],"verses":[[15,"Přišli do Jeruzaléma. A vešel Ježíš do chrámu, počal vymítati ty, kteříž prodávali a kupovali v chrámě, a stoly penězoměnců a stolice prodávajících holuby převracel."],[16,"nedopustil, aby kdo nádobu nesl skrze chrám."],[17,"I učil je, řka jim: Zdaliž není psáno, že dům můj dům modlitby slouti bude u všech národů? Vy pak udělali jste ho peleší lotrů."],[18,"Slyšeli pak to zákonníci i přední kněží {biskupové}, a hledali, kterak by ho zahubili; nebo se ho báli, proto že celý zástup divil se učení jeho."],[19,"když byl večer, vyšel z města."]]},{"title":"Poučení z fíkovníku","range":"Mk 11,20–26","thoughts":[],"verses":[[20,"když šli ráno, uviděli ten fík, an usechl z kořene."],[21,"Potom zpomenuv Petr, řekl mu: Mistře, aj, ten fík, kterémuž jsi zlořečil, usechl."],[22,"I odpověděl Ježíš, řekl jim: Mějte víru Boží."],[23,"Protože amen říkám vám, že kdož bykoli řekl hoře této: Zdvihni se a vrz seboudo moře, a nepochyboval by v srdci svém, ale věřil by, že se stane, cokoli dí, staneťse mu tak, což by koli řekl."],[24,"Protož říkám vám: Zač byste koli, modléce se, prosili, věřte, že vezmete, a staneť se vám."],[25,"když se postavíte k modlení, odpouštějte, máte-li co proti komu, aby i Otec váš nebeský odpustil vám hříchy vaše."],[26,"Protože jestliže vy neodpustíte, ani Otec váš, kterýž v nebesích je, odpustí vám hříchů vašich."]]},{"title":"Otázka Ježíšovy autority","range":"Mk 11,27–33","thoughts":[],"verses":[[27,"Přišli zase do Jeruzaléma. A když on procházel se v chrámě, přistoupili k němu přední kněží {biskupové} a zákonníci a starší."],[28,"I řekli mu: Jakou mocí to činíš? A kdo tobě dal tu takovou moc, abys tyto věci činil?"],[29,"Potom odpovídaje Ježíš, řekl jim: Otížiť se i já vás na jednu věc. Odpovězte mi, a povím vám, jakou mocí to činím."],[30,"Křest Janův s nebe-li byl, čili z lidí? Odpovězte mi."],[31,"I rozjímali sami mezi sebou, řkouce: Díme-li: S nebe, díť: Proč jste tedy neuvěřili mu?"],[32,"Pakli řeklme: Z lidí, bojíme se lidu. Protože všichni o Janovi smyslili, že právě byl prorok."],[33,"I odpovědělše, řekli Ježíšovi: Nevíme. A Ježíš odpovídaje, řekl jim: Aniž já vám povím, jakou mocí to činím."]]}];

MARK_SECTIONS["12"] = [{"title":"Podobenství o zlých vinařích","range":"Mk 12,1–12","thoughts":[],"verses":[[1,"Potom počal jim mluviti v podobenstvích: Vinici štípil člověk, a opletl ji plotem, a vkopal pres, a ustavěl věži, a pronajal ji vinařům, i odšel na cestu."],[2,"když toho čas byl, poslal k vinařům služebníka, aby od vinařů vzal ovoce z vinice."],[3,"Oni pak javše ho, zmrskali ho, a odeslali prázdného."],[4,"I poslal k nim zase jiného služebníka. I toho též kamenovavše, ranili v hlavu, a odeslali zohaveného."],[5,"I poslal znovu jiného. I toho zabili, a mnoho jiných, z nichž některé zmrskali, a jiné zmordovali."],[6,"Ještě pak měl jediného syna milého, i toho poslal k nim naposledy, řka: Ustýdnouť se syna mého."],[7,"Ale vinaři řekli jedni k druhým: Tentoť je dědic; pojďte, zabíme ho, a budeť naše dědictví."],[8,"Potom javše ho, zabili ho, a vyvrhli ven z vinice."],[9,"Což tedy učiní pán vinice? Přijde, a zatratí vinaře ty, a dá vinici jiným."],[10,"Zdaliž jste písma toho nečtli? Kámen, kterýž zavrhli stavitelé, ten učiněn je hlavou úhlovou."],[11,"Ode Pána stalo se toto, a je divné před očima našima."],[12,"I hledali ho jíti, ale báli se zástupu; nebo poznali, že podobenství to proti nim pověděl. A nechavše ho, odešli pryč."]]},{"title":"Daň císaři","range":"Mk 12,13–17","thoughts":[],"verses":[[13,"Potom poslali k němu některé z farizeů a Herodiánů, aby ho polapili v řeči."],[14,"Kteřížto když přišelše, řekli mu: Mistře, víme, že jsi pravdomluvný, a nedbáš na žádného; nebo nepatříš na osobu lidskou, ale v pravdě cestě Boží učíš. Sluší-li daň dávati císaři, čili nic? Dáme-liž, čili nedáme?"],[15,"On pak znaje pokrytství jejich, řekl jim: Co mne pokoušíte? Přineste mi minci, ať pohledím."],[16,"oni podali. Potom řekl jim: Čí je tento obraz a nápis? A oni řekli mu: Císařův."],[17,"I odpověděl Ježíš, řekl jim: Dávejtež tedy, což je císařova, císaři, a což je Božího, Bohu. I podivili se tomu."]]},{"title":"Otázka vzkříšení","range":"Mk 12,18–27","thoughts":[],"verses":[[18,"Potom přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho, řkouce:"],[19,"Mistře, Mojžíš nám napsal: Kdyby čí bratr umřel, a ostavil manželku, a synů by neměl, aby bratr jeho pojal manželku jeho, a vzbudil símě bratru svému."],[20,"I bylo sedm bratrů. A první pojav manželku, a umřev, napozůstavil semene."],[21,"druhý pojav ji, také umřel, a aniž ten ostavil semene. A třetí tolikéž."],[22,"tak ji pojalo těch sedm, a nezůstavili semene. Nejposléze pak po všech umřela i ta žena."],[23,"Protož při vzkříšení, když z mrtvých vstanou, čí z těch bude manželka? Protože jich sedm mělo ji za manželku."],[24,"odpovídaje Ježíš, řekl jim: Zdaliž ne proto bloudíte, že neznáte písem ani moci Boží?"],[25,"Protože když vstanou z mrtvých, nebudou se ženiti ani vdávati, ale budou jako andělé nebeští."],[26,"O mrtvých pak, že mají vstáti, zdaž jste nečtli v knize Mojžíšově, kterak ve kři promluvil k němu Bůh, řka: Já jsem Bůh Abrahamův, a Bůh Izákův, a Bůh Jákobův?"],[27,"Neníť Bůh mrtvých, ale Bůh živých. Protož vy velmi bloudíte."]]},{"title":"Největší přikázání","range":"Mk 12,28–34","thoughts":[],"verses":[[28,"Potom přistoupil jeden z zákonníků, slyšev je spolu se hádající, a vida, že jim dobře odpověděl, otázal se ho: Které je přikázaní první ze všech?"],[29,"Ježíš odpověděl mu, že první ze všech přikázaní je: Slyš, Izraeli, Pán Bůh náš Pán jeden je."],[30,"Protož milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší mysli své, i ze všech mocí svých. To je první přikázaní."],[31,"Druhé pak podobné toto: Milovati budeš bližního svého jako sebe samého. Většího přikázaní jiného nad tato není."],[32,"Řekl mu ten zákonník: Mistře, dobře jsi v pravdě pověděl. Protože jeden je Bůh, a není jiného kromě něj;"],[33,"milovati ho ze všeho srdce, a ze vší mysli, a ze vší duše, i ze všech mocí, a milovati bližního jako sebe samého je nade všechny zápaly a oběti."],[34,"když viděl Ježíš, že by moudře odpověděl, dí mu: Nejsi daleko od království Božího. A žádný více nesměl se ho tázati."]]},{"title":"Čí syn je Mesiáš","range":"Mk 12,35–37","thoughts":[],"verses":[[35,"I odpovídaje Ježíš, řekl, uče v chrámě: Kterak praví zákonníci, že Kristus je syn Davidův?"],[36,"Protože David praví v Duchu svatém: Řekl Pán Pánu mému: Seď na pravici mé, ažť i položím nepřátely tvé za podnože noh tvých."],[37,"Poněvadž sám David nazývá ho Pánem, kterakž tedy syn jeho je? A mnohý zástup rád ho poslouchal."]]},{"title":"Varování před zákoníky","range":"Mk 12,38–40","thoughts":[],"verses":[[38,"I mluvil jim v učení svém: Varujte se zákonníků, kteříž chtějí v krásném rouše choditi, a pozdravováni býti na trzích,"],[39,"na předních stolicech seděti v školách, a přední místa míti na večeřech,"],[40,"Kteřížto zžírají domy vdovské, a to pod zámyslem dlouhých modliteb. Tiť vezmou soud těžší."]]},{"title":"Dar chudé vdovy","range":"Mk 12,41–44","thoughts":[],"verses":[[41,"posadiv se Ježíš proti pokladnici, řeklval se, kterak zástup metal peníze do pokladnice. A mnozí bohatí metali mnoho."],[42,"když přišelši jedna chudá vdova, i vrhla dva šarty, což je čtvrtá částka peníze."],[43,"I svolav učedlníky své, dí jim: Amen, říkám vám, že tato chudá vdova více uvrhla, než tito všichni, kteříž metali do pokladnice."],[44,"Protože všichni z toho, což jim zbývalo, metali, ale tato z své chudoby, všechno, což měla, uvrhla, všecku živnost svou."]]}];

MARK_SECTIONS["13"] = [{"title":"Proroctví o zničení chrámu","range":"Mk 13,1–4","thoughts":[],"verses":[[1,"když vycházel z chrámu, dí mu jeden z učedníků jeho: Mistře, pohleď, kteraké kamení a jaké stavení!"],[2,"Potom Ježíš odpovídaje, řekl mu: Vidíš tato tak veliká stavení? Nebudeť ostaven kámen na kameni, kterýž by nebyl zbořen."],[3,"když se posadil na hoře Olivetské proti chrámu, otázali se jeho soukromí Petr, Jakub a Jan a Ondřej:"],[4,"Pověz nám, kdy to bude? A které znamení, když se toto všechno bude plniti?"]]},{"title":"Války a pronásledování","range":"Mk 13,5–13","thoughts":[],"verses":[[5,"Ježíš pak odpovídaje jim, počal praviti: Vizte, aby vás někdo nesvedl."],[6,"Protožeť mnozí přijdou ve jménu mém, řkouce: Já jsem Kristus, a mnohéť svedou."],[7,"Když pak uslyšíte o boji a pověst o válkách, nestrachujte se; nebo musí to býti, ale ne i hned konec."],[8,"Povstaneť zajisté národ proti národu a království proti království, a budou země třesení po místech, a hladové i bouřky."],[9,"toť počátkové bolestí. Vy pak šetřte se. Protože vydávati vás budou na sněmy a do shromáždění; budete biti, a před vládaři a králi stanete pro mne, na svědectví jim."],[10,"Ale ve všech národech nejprv musí býti kázáno evangelium."],[11,"Když pak vás povedou, vyzrazujíce, nestarejte se předtím, co byste mluvili, aniž pečlivě přemyšlujte, ale což vám bude dáno v tu hodinu, to mluvte; nebo nejste vy, kteříž mluvíte, ale Duch svatý."],[12,"Vydáť pak bratr bratra na smrt a otec syna, a povstanou děti proti rodičům, a budou je mordovati."],[13,"budete v nenávisti všechněm pro jméno mé. Ale kdož setrvá až do konce, tenť spasen bude."]]},{"title":"Velké soužení","range":"Mk 13,14–23","thoughts":[],"verses":[[14,"Když pak uzříte ohavnost zpuštění, o kteréž pověřeklno je skrze Daniele proroka, ana stojí, kdež by státi neměla, (kdo čte, rozuměj), tehdáž ti, kdož by v Židovstvu byli, ať utekou na hory."],[15,"kdož by na střeše byl, nesstupuj do domu, ani vcházej, aby co vzal z domu svého."],[16,"kdo na poli, nevracuj se zase, aby vzal oděv své."],[17,"Běda pak těhotným a těm, kteréž krmí v těch dnech."],[18,"Protož modlte se, aby utíkání vaše nebylo v zimě."],[19,"Protožeť budou ti dnové ssoužení, jakéhož nebylo od počátku stvoření, kteréž Bůh stvořil, až dosavad, aniž bude."],[20,"byť nebyl ukrátil Pán těch dnů, nebyl by spasen žádný člověk. Ale pro vyvolené, kteréž vyvolil, ukrátil těch dnů."],[21,"tehdáž řekl-li by vám kdo: Hle, teď je Kristus, aneb aj, tamto, nevěřte."],[22,"Protožeť povstanou falešní Kristové a falešní proroci, a budou činiti divy a zázraky k svedení, by možné bylo, také i vyvolených."],[23,"Vy pak šetřte se. Hle, předpověděl jsem vám všechno."]]},{"title":"Příchod Syna člověka","range":"Mk 13,24–27","thoughts":[],"verses":[[24,"V těch pak dnech, po ssoužení tom, slunce se zatmí, a měsíc nedá světla svého."],[25,"hvězdy nebeské budou padati, a moci, které jsou na nebi, pohnou se."],[26,"tehdážť uzří Syna člověka, an se béře v oblacích s mocí velikou a s slávou."],[27,"I tehdyť pošle anděly své, a shromáždí vyvolené své ode čtyř větrů, od končin země až do končin nebe."]]},{"title":"Podobenství o fíkovníku","range":"Mk 13,28–31","thoughts":[],"verses":[[28,"Od fíku pak učte se podobenství tomuto: Když již ratolest jeho odmladne, a vypučí se lístí, znáte, že blízko je léto."],[29,"Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko je a ve dveřích."],[30,"Amen, říkám vám, žeť nepomine pokolení toto, až se tyto všechny věci stanou."],[31,"Nebe a země pominou, ale slova má ne nepominou."]]},{"title":"Bděte","range":"Mk 13,32–37","thoughts":[],"verses":[[32,"Ale o tom dni a hodině žádný neví, ani andělé, kteříž jsou v nebesích, ani Syn, jediné Otec."],[33,"Vizte, bděte a modlte se; nebo nevíte, kdy bude ten čas."],[34,"Jako člověk, kterýž daleko odšel, opustiv dům svůj, a poručiv služebníkům svým vládařství, a jednomu každému práci jeho, vrátnému přikázal, aby bděl."],[35,"Protož bděte; nebo nevíte, kdy Pán domu přijde, u večer-li, čili o půlnoci, čili když kohouti zpívají, čili ráno."],[36,"Aby snad přijda v nenadále, nenalezl vás, a vy spíte."],[37,"cožť vám říkám, všechněmť říkám: Bděte."]]}];

MARK_SECTIONS["14"] = [{"title":"Spiknutí proti Ježíšovi","range":"Mk 14,1–2","thoughts":[],"verses":[[1,"Po dvou pak dnech byl hod beránka a přesnic; i hledali přední kněží a zákonníci, jak by ho lstivě jmouce, zamordovali."],[2,"Ale říkali: Ne v svátek, aby snad nebyl rozbroj v lidu."]]},{"title":"Pomazání v Betanii","range":"Mk 14,3–9","thoughts":[],"verses":[[3,"když byl v Betany, v domu Šimona malomocného, a seděl za stolem, přišla žena, mělaí nádobu alabastrovou masti velmi drahé, z nardového koření. A rozbivši alabastrovou nádobu, vylila ji na hlavu jeho."],[4,"hněvali se někteří mezi sebou, řkouce: A proč ztráta masti této stala se?"],[5,"Protože mohlo toto prodáno býti, dráže než za tři sta peněz, a dáno býti chudým. A zpouzeli se na ni."],[6,"Ale Ježíš řekl: Nechte jí. Proč ji rmoutíte? Dobrýť skutek učinila nade mnou."],[7,"Však chudé máte vždycky s sebou, a když budete chtíti, můžete jim dobře činiti, ale mne ne vždycky míti budete."],[8,"Ona což mohla, to učinila; předešlať, aby těla mého pomazala ku pohřebu."],[9,"Amen, říkám vám: Kdežkoli bude kázáno toto evangelium po všem světě, takéť i to, což učinila tato, bude vypravováno na památku hoí."]]},{"title":"Jidášova zrada","range":"Mk 14,10–11","thoughts":[],"verses":[[10,"Jidáš Aškariotský, jeden ze dvanácti, odšel k předním kněžím {biskupům}, aby jim ho zradil."],[11,"Oni pak uslyševše, zradovali se, a slíbili mu peníze dáti. A hledal, jak by ho příhodně zradil."]]},{"title":"Příprava velikonoční večeře","range":"Mk 14,12–16","thoughts":[],"verses":[[12,"Prvního pak dne přesnic, když velikonoční beránek zabíjín býval, řkou mu učedlníci jeho: Kde chceš, ať když šli, připravíme, abys jedl beránka?"],[13,"poslal dva z učedníků svých, a řekl jim: Jděte do města, a potkáť vás člověk dčbán vody nesa. Jdětež za ním."],[14,"kamžkoli vejde, rcete hospodáři: Mistrť praví: Kde je večeřadlo, v němž bych jedl beránka s učedníky svými?"],[15,"on vám ukáže večeřadlo veliké, podlážené a připravené. Tu nám připravte."],[16,"odešli učedlníci jeho, a přišli do města, a nalezli tak, jakož jim byl pověděl. A připravili beránka."]]},{"title":"Poslední večeře","range":"Mk 14,17–25","thoughts":[],"verses":[[17,"Když pak byl večer, přišel se dvanácti."],[18,"když seděli za stolem a jedli, řekl Ježíš: Amen, říkám vám, že jeden z vás mne zradí, kterýž jí se mnou."],[19,"oni se počali rmoutiti, a praviti mu jeden každý obzvláštně: Zdali já jsem? A jiný: Zdali já?"],[20,"On pak odpověděv, řekl jim: Jeden ze dvanácti, kterýž omáčívá se mnou v mise."],[21,"Syn zajisté člověka jde, jakož psáno o něm, ale běda člověku tomu, skrze nějž Syn člověka bude zrazen. Dobré by bylo mu, aby se byl nenarodil člověk ten."],[22,"když oni jedli, vzav Ježíš chléb, a dobrořečiv, lámal a dával jim, řka: Vezměte, jezte, to je tělo mé."],[23,"vzav kalich, a řeklky učiniv, dal jim. A pili z něj všichni."],[24,"řekl jim: To je krev má smlouvy té nové, kteráž se za mnohé vylévá."],[25,"Amen, říkám vám, žeť již více nikoli nebudu píti z plodu vinného kořene, až do onoho dne, když ho píti budu nový v království Božím."]]},{"title":"Petr zapření předpovězeno","range":"Mk 14,26–31","thoughts":[],"verses":[[26,"sezpívavše písničku, vyšli na horu Olivetskou."],[27,"řekl jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Protože psáno je: Bíti budu pastýře, a rozprchnou se ovce."],[28,"Ale když z mrtvých vstanu, předejduť vás do Galilee."],[29,"Petr řekl mu: Byť se pak všichni zhoršili, ale já nic."],[30,"řekl mu Ježíš: Amen říkám tobě, že dnes této noci, prvé než kohout po dvakrát zazpívá, třikrát mne zapříš."],[31,"On pak mnohem více mluvil: Bychť pak měl s tebou i umříti, nikoliť nezapřím tebe. A takž také i všichni mluvili."]]},{"title":"Ježíš v Getsemanech","range":"Mk 14,32–42","thoughts":[],"verses":[[32,"přišli na místo, kterémuž jméno Getsemany. Potom řekl učedníkům svým: Seďtež tuto, až se pomodlím."],[33,"pojav s sebou Petra a Jakuba a Jana, počal se lekati a velmi teskliv býti."],[34,"dí jim: Smutnáť je duše má až k smrti. Počekejtež tuto a bděte."],[35,"poodšel maličko, padl na zemi a modlil se, aby, bylo-li by možné, odešla od něj hodina ta."],[36,"řekl: Abba, Otče, všechno je možné tobě. Přenes kalich tento ode mne, ale však ne, což já chci, ale co ty."],[37,"přišel a nalezl je, ani spí. A řekl Petrovi: Šimone, spíš? Nemohl-lis jediné hodiny bdíti?"],[38,"Bděte a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov je, ale tělo nemocno."],[39,"znovu odšel, modlil se, táž slova mluvě."],[40,"navrátiv se, nalezl je, ani znovu spí, (nebo oči jejich byly obtíženy); aniž věděli, co by mu odpověděli."],[41,"přišel po třetí, a řekl jim: Spětež již a odpočívejte; dostiť je. Přišlať ta hodina; aj, Syna člověka zrazují v ruce hříšných."],[42,"Vstaňte, pojďme. Hle, kterýž mne zrazuje, blízkoť je."]]},{"title":"Ježíšovo zatčení","range":"Mk 14,43–52","thoughts":[],"verses":[[43,"hned, když on ještě mluvil, přišel Jidáš, kterýž byl jeden ze dvanácti, a s ním zástup veliký s meči a s kyjmi, od předních kněží {biskupů} a od zákonníků a starších."],[44,"Zrádce pak jeho byl jim dal znamení, řka: Kteréhožkoli políbím, tenť je; jmětež ho, a veďte opatrně."],[45,"přišel, hned přistoupiv k němu, řekl: Mistře, Mistře, a políbil ho."],[46,"oni vztáhli naň ruce své, a jali ho."],[47,"Jeden pak z těch, kteříž tu okolo stáli, vytrh meč, udeřil služebníka nejvyššího kněze, a uťal mu ucho."],[48,"odpověděv Ježíš, řekl jim: Jako na lotra vyšli jste s meči a s kyjmi, abyste mne jali?"],[49,"Na každý den býval jsem u vás, uče v chrámě, a nejali jste mne. Ale aby se naplnila písma."],[50,"opustivše ho, všichni utekli."],[51,"Jeden pak mládenček šel za ním, odín když byl rouchem lněným po nahém těle. A popadli ho mládenci."],[52,"On pak opustiv oděv, nahý utekl od nich."]]},{"title":"Ježíš před radou","range":"Mk 14,53–65","thoughts":[],"verses":[[53,"přivedli Ježíše k nejvyššímu knězi {biskupovi}, a sešli se k němu všichni přední kněží i starší i zákonníci."],[54,"Petr pak šel za ním zdaleka až na dvůr nejvyššího kněze {biskupův}; i seděl s služebníky, zhřívaje se u ohně."],[55,"Ale přední kněží i všechna ta rada hledali proti Ježíšovi svědectví, aby ho na smrt vydali, a však nenalezli."],[56,"Protože ač mnozí křivé svědectví vydávali proti němu, však svědectví jejich nebyla jednostejná."],[57,"někteří vstalše, křivé svědectví dávali proti němu, řkouce:"],[58,"My jsme slyšeli tohoto, že řekl: Já zbořím chrám tento rukou udělaný, a ve třech dnech jiný ne rukou udělaný postavím."],[59,"Ale ani to jejich svědectví nebylo jednostejné."],[60,"vstal nejvyšší kněz u prostřed, otázal se Ježíše, řka: Neodpovídáš ničeho, což tito na tebe svědčí?"],[61,"Ale on mlčel, a nic neodpověděl. Opět nejvyšší kněz otázal se ho a řekl mu: Jsi-liž ty Kristus, ten Syn toho Požehnaného?"],[62,"Ježíš řekl: Jáť jsem, a uzříte Syna člověka, an sedí na pravici moci Boží, a přichází s oblaky nebeskými."],[63,"nejvyšší kněz roztrh oděvy svá, řekl: A což ještě potřebujeme svědků?"],[64,"Slyšeli jste rouhání. Co se vám zdá? Oni pak všichni potupili ho, že je hoden smrti."],[65,"počali někteří naň plvati, a tvář jeho zakrývati, a ho poličkovati, a říkati mu: Prorokuj. A služebníci kyji ho bili."]]},{"title":"Petr zapírá Ježíše","range":"Mk 14,66–72","thoughts":[],"verses":[[66,"když byl Petr v síni dole, přišla jedna z děvek nejvyššího kněze {biskupových}."],[67,"když uvidělši Petra, an se ohřívá, a popatřivši naň, dí: A ty s Ježíšem Nazaretským byl jsi."],[68,"Ale on zapřel, řka: Aniž vím, ani rozumím, co ty pravíš. A vyšel ven před síň, a kohout zazpíval."],[69,"děvka, když uvidělši ho znovu, počala praviti těm, kteříž tu okolo stáli, že tento z nich je."],[70,"on znovu zapřel. A po malé chvíli znovu ti, kteříž tu stáli, řekli Petrovi: Jistě z nich jsi, nebo i Galilejský jsi, i řeč tvá podobná je."],[71,"On pak počal se proklínati a přisahati: Neznám člověka toho, o němž říkáte."],[72,"hned po druhé kohout zazpíval. A rozpomenul se Petr na slovo, kteréž byl řekl mu Ježíš: Že prvé než kohout dvakrát zazpívá, třikrát mne zapříš. A vyšel, plakal."]]}];

MARK_SECTIONS["15"] = [{"title":"Ježíš před Pilátem","range":"Mk 15,1–15","thoughts":[],"verses":[[1,"hned ráno, uradivše se přední kněží s staršími a s zákonníky i se vším shromážděním, svázavše Ježíše, vedli ho a dali Pilátovi."],[2,"otázal se ho Pilát: Ty-li jsi ten král Židovský? A on odpověděv, řekl mu: Ty pravíš?"],[3,"žalovali na něj přední kněží mnoho. On pak nic neodpovídal."],[4,"Pilát otázal se ho znovu, řka: Nic neodpovídáš? Hle, jak mnoho proti tobě svědčí."],[5,"Ale Ježíš předce nic neodpověděl, tak že se podivil Pilát."],[6,"V svátek pak propouštíval jim jednoho z vězňů, za kteréhož by koli prosili."],[7,"byl jeden, kterýž sloul Barabáš, s svárlivými v vězení, kteříž v svadě vraždu byli spáchali."],[8,"zvolav zástup, počal prositi, aby udělal, jakož jim vždycky činíval."],[9,"Pilát pak odpověděl jim, řka: Chcete-li, propustím vám krále Židovského?"],[10,"(Protože věděl, že ho z závisti vydali přední kněží)."],[11,"Ale přední kněží ponukli zástupu, aby jim raději propustil Barabáše."],[12,"Pilát odpověděv, řekl jim zase: Což pak chcete, ať udělám tomu, kteréhož králem Židovským nazýváte?"],[13,"oni znovu zvolali: Ukřižuj ho."],[14,"Pilát řekl jim: A co zlého udělal? Oni pak více volali: Ukřižuj ho."],[15,"Pilát, chtě lidu dosti udělat, pustil jim Barabáše, a dal jim Ježíše ubičovaného, aby byl ukřižován."]]},{"title":"Vojáci se Ježíšovi posmívají","range":"Mk 15,16–20","thoughts":[],"verses":[[16,"Žoldnéři pak uvedli ho vnitř do síně, do rathouzu, a svolali všecku zběř."],[17,"oblékli ho v šarlat, a korunu zpletše z trní, vložili naň."],[18,"počali ho pozdravovati: Zdráv buď, králi Židovský."],[19,"bili hlavu jeho třtinou, a plili na něj, a sklánějíce kolena, klaněli se mu."],[20,"když se mu naposmívali, svlékli s něj šarlat, a oblékli ho v oděv jeho vlastní. A vedli ho, aby ho ukřižovali."]]},{"title":"Ukřižování","range":"Mk 15,21–32","thoughts":[],"verses":[[21,"přinutili nějakého Šimona Cyrenenského, pomíhoícího, (kterýž šel z pole, otce Alexandrova a Rufova), aby nesl kříž jeho."],[22,"vedli ho až na místo Golgota, to je, (vyložil-li by), popravné místo."],[23,"dávali mu píti víno s mirrou, ale on nepřijal."],[24,"ukřižovavše ho, rozdělili oděvy jeho, mecíce o ně los, kdo by co vzíti měl."],[25,"byla hodina třetí, když ho ukřižovali."],[26,"byl nápis viny jeho napsán: Král Židovský."],[27,"Ukřižovali také s ním dva lotry, jednoho na pravici, a druhého na levici jeho."],[28,"naplněno je písmo, řkoucí: A s nepravými počten je."],[29,"kteříž chodili mimo něj, rouhali se mu, potřásajíce hlavami svými, a říkajíce: Hahá, kterýž rušíš chrám, a ve třech dnech vzděláváš,"],[30,"Spomoz sobě samému, a sstup s kříže."],[31,"Též i přední kněží posmívajíce se, jeden k druhému s zákonníky říkali: Jinýmť pomáhal, sám sobě pomoci nemůže."],[32,"Kristus, ten král Izraelský, nechažť nyní sstoupí s kříže, ať uzříme, a uvěříme. A i ti, kteříž s ním ukřižování byli, útržku mu činili."]]},{"title":"Ježíšova smrt","range":"Mk 15,33–41","thoughts":[],"verses":[[33,"když byla hodina šestá, stala se tma po vší zemi až do hodiny deváté."],[34,"v hodinu devátou zvolal Ježíš hlasem velikým, řka: Elói, Elói, lama zabachtani? Což se vykládá: Bože můj, Bože můj, pročs mne opustil?"],[35,"někteří z okolo stojících, slyševše to, říkali: Hle, Eliáše volá."],[36,"běžev jeden, naplnil hubu octem, a vloživ na tresť, dával mu píti, řka: Ponechte, uzříme, přijde-li Eliáš, aby ho složil."],[37,"Ježíš pak zvolav hlasem velikým, pustil duši."],[38,"opona v chrámě roztrhla se na dvé, od vrchu až dolů."],[39,"Viděv pak centurio, kterýž tu naproti stál, že tak volaje, vypustil duši, řekl: Jistě člověk tento Syn Boží byl."],[40,"Byly pak tu i ženy, zdaleka se řeklvajíce, mezi nimiž byla Maria Magdaléna, a Maria Jakuba menšího, a Jozesova mátě, a Salome,"],[41,"Kteréž, když ještě byl v Galilei, chodily za ním a posluhovaly mu, i jiné mnohé, kteréž byly s ním vstoupily do Jeruzaléma."]]},{"title":"Ježíšův pohřeb","range":"Mk 15,42–47","thoughts":[],"verses":[[42,"když již byl večer, (že byl den připravování, to je před sobotou),"],[43,"Přišel Jozef z Arimatie, počestná osoba úřadná, kterýž také očekával království Božího, směle všel ku Pilátovi, a prosil za tělo Ježíšovo."],[44,"Pilát pak podivil se, již-li by umřel. A povolav centuriona, otázal se ho, dávno-li je umřel."],[45,"zvěděv od centuriona, dal tělo Jozefovi."],[46,"koupiv plátna, a sňav ho, obvinul v plátno, a položil do hrobu, kterýž byl vytesán z skály, a přivalil kámen ke dveřům hrobovým."],[47,"Ale Maria Magdaléna a Maria Jozesova řeklvaly se, kde by byl položen."]]}];

MARK_SECTIONS["16"] = [{"title":"Prázdný hrob","range":"Mk 16,1–8","thoughts":[],"verses":[[1,"když pominula sobota, Maria Magdaléna a Maria Jakubova a Salome nakoupily vonných věcí, aby přijdouce, pomazaly Ježíše."],[2,"Protož velmi ráno v první den po sobotě přišly k hrobu, an již slunce vzešlo."],[3,"pravily vespolek: Kdo nám odvalí kámen ode dveří hrobových?"],[4,"(A vzhlédše, uzřely odvalený kámen.) Byl zajisté veliký velmi."],[5,"všelše do hrobu, uzřely mládence, an sedí na pravici, oděného rouchem bílým. A ulekly se."],[6,"On pak řekl jim: Nebojte se. Ježíše hledáte Nazaretského, toho ukřižovaného. Vstalť je, neníť ho tuto; aj, místo, kdež ho byli položili."],[7,"Ale jděte, povězte učedníkům jeho i Petrovi, žeť vás předejde do Galilee. Tam ho uzříte, jakž pověděl vám."],[8,"vyšelše rychle, utekly od hrobu; nebo přišel na ně strach a hrůza. A aniž komu co řekly, nebo se bály."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Mk 16,9–14","thoughts":[],"verses":[[9,"Vstav pak Ježíš z mrtvých ráno v neděli, ukázal se nejprv Marii Magdaléně, z níž byl vyvrhl sedm ďáblů."],[10,"Ona pak šedši, zvěstovala těm, kteříž s ním bývali, lkajícím a plačícím."],[11,"oni když uslyšelše, že by živ byl, a vidín od ní, nevěřili."],[12,"pak dvěma z nich jdoucím ukázal se v jiné způsobě, když šli přes pole."],[13,"ti šedše, pověděli jiným. Ani těm nevěřili."],[14,"sedícím spolu jedenácti ukázal se, a trestal nedověru jejich a tvrdost srdce, že těm, kteříž ho viděli vzkříšeného, nevěřili."]]},{"title":"Poslání učedníků","range":"Mk 16,15–20","thoughts":[],"verses":[[15,"řekl jim: Jdouce po všem světě, kažte evangelium všemu stvoření."],[16,"Kdož uvěří a pokřtí se, spasen bude; kdož pak neuvěří, budeť zatracen."],[17,"Znamení pak ti, kteříž uvěří, tato míti budou: Ve jménu mém ďábly budou vymítati, jazyky novými mluviti,"],[18,"Hady bráti, a jestliže by co jedovatého pili, nikoliť jim neuškodí; na nemocné ruce vzkládati budou, a dobře se míti budou."],[19,"Když pak jim odmluvil Pán, zhůru vzat je do nebe, a sedí na pravici Boží."],[20,"oni vyšelše, kázali všudy, a Pán jim pomáhal, a slov jejich potvrzoval činěním divů."]]}];

